<section id="time" class="panel tracking-panel" data-ticket-panel data-ticket-live aria-labelledby="ticket-tab-time" hidden>
 <div class="panel-header"><div><h2>Suivi du temps</h2><p>Le temps passé est indépendant de l’avancement manuel.</p></div><?= icon('clock') ?></div>
 <div class="tracking-metrics"><div><small>Estimation totale</small><strong><?= e(App\Core\View::hours($ticket['estimated_hours'])) ?></strong></div><div><small>Temps passé</small><strong><?= e(App\Core\View::hours($ticket['spent_hours'])) ?></strong></div><div><small>Reste à faire · <?= (int)$ticket['progress_percent'] ?> %</small><strong><?= e(App\Core\View::hours($ticket['remaining_hours'])) ?></strong></div></div>
 <p class="help-text">Reste à faire = estimation totale × (100 − avancement) / 100. Sans estimation, le reste à faire n’est pas calculé.</p>
 <?php if($canEdit && !$ticket['archived']): ?><details class="tracking-add"><summary class="button subtle"><?= icon('plus') ?>Saisir du temps</summary><form action="/tickets/<?= (int)$ticket['id'] ?>/time" method="post" class="stack details-content" data-tracking-form><?= csrf() ?><?= ticket_context() ?><input type="hidden" name="version" value="<?= (int)$ticket['version'] ?>"><input type="hidden" name="_return" value="<?= e(ticket_url((int)$ticket['id']).'#time') ?>"><div class="inline-fields"><label>Date<input type="date" name="worked_on" value="<?= gmdate('Y-m-d') ?>" max="<?= gmdate('Y-m-d') ?>" required></label><label>Durée (heures)<input name="hours" inputmode="decimal" placeholder="Ex. : 1,5" required></label></div><label>Travail réalisé<textarea name="note" rows="2" maxlength="2000"></textarea></label><button class="button primary">Enregistrer le temps</button></form></details><?php endif; ?>
 <div class="worklog-list"><?php foreach($time['entries'] as $entry): ?><article class="worklog-entry"><div class="worklog-heading"><strong><?= e(App\Core\View::hours($entry['hours'])) ?></strong><span><?= e($entry['name']) ?></span><time><?= e($entry['worked_on']) ?></time></div><?php if($entry['note']!==''): ?><p class="tracking-text"><?= e($entry['note']) ?></p><?php endif; ?>
 <?php if($canEdit && !$ticket['archived'] && ($user['role']==='admin' || (int)$entry['user_id']===(int)$user['id'])): ?><details><summary class="text-button">Modifier cette saisie</summary><form action="/tickets/<?= (int)$ticket['id'] ?>/time" method="post" class="stack details-content" data-tracking-form><?= csrf() ?><?= ticket_context() ?><input type="hidden" name="version" value="<?= (int)$ticket['version'] ?>"><input type="hidden" name="entry_id" value="<?= (int)$entry['id'] ?>"><div class="inline-fields"><label>Date<input type="date" name="worked_on" value="<?= e($entry['worked_on']) ?>" max="<?= gmdate('Y-m-d') ?>" required></label><label>Durée (heures)<input name="hours" inputmode="decimal" value="<?= e($entry['hours']) ?>" required></label></div><label>Travail réalisé<textarea name="note" rows="2" maxlength="2000"><?= e($entry['note']) ?></textarea></label><div class="tracking-actions"><button class="button subtle">Enregistrer</button><button class="button danger-outline" name="action" value="delete" data-tracking-confirm="Supprimer cette saisie de temps ? Sa trace restera dans l’historique.">Supprimer</button></div></form></details><?php endif; ?></article><?php endforeach; if(!$time['entries']): ?><p class="empty-state">Aucun temps saisi pour ce ticket.</p><?php endif; ?></div>
 <?php if($time['total']>$time['limit']): ?><nav class="pagination" aria-label="Pages des saisies de temps"><?php if($time['offset']): ?><a class="button subtle" href="<?= e(ticket_url((int)$ticket['id'],'#time',['time_offset'=>max(0,$time['offset']-$time['limit'])])) ?>">Précédent</a><?php endif; ?><span><?= $time['offset']+1 ?>–<?= min($time['total'],$time['offset']+$time['limit']) ?> sur <?= $time['total'] ?></span><?php if($time['offset']+$time['limit']<$time['total']): ?><a class="button subtle" href="<?= e(ticket_url((int)$ticket['id'],'#time',['time_offset'=>($time['offset']+$time['limit'])])) ?>">Suivant</a><?php endif; ?></nav><?php endif; ?>
</section>
